  if ((obj.name_ == nullptr) && (other.name_ == nullptr)) {
    return false;
  } else if (obj.name_ == nullptr) {
    return false;
  } else if (other.name_ == nullptr) {
    return true;
  } else {
    return (*(obj.name_)) > (*(other.name_));
  }
